// This method does not clear the JIT hash table.  To do that, use:
//
//      GrB.jit ('flush') ;

#include "gb_interface.h"
#include "gbmx_interface.h"

void mexFunction
(
    int nargout,
    mxArray *pargout [ ],
    int nargin,
    const mxArray *pargin [ ]
)
{

    //--------------------------------------------------------------------------
    // get test coverage
    //--------------------------------------------------------------------------

    gbcov_get ( ) ;

    //--------------------------------------------------------------------------
    // initialize GraphBLAS if necessary
    //--------------------------------------------------------------------------

    GBMX_USAGE (true, "") ;

    ////////////////////////////////////////////////////////////////////////////

    //--------------------------------------------------------------------------
    // set global defaults
    //--------------------------------------------------------------------------

    OK (gbmx_defaults (err)) ;

    //--------------------------------------------------------------------------
    // save test coverage
    //--------------------------------------------------------------------------

    gb_wrapup ( ) ;
}

